1	// Regras da lista de pendências. Funções puras: recebem a lista, devolvem uma lista nova.
2	
3	export function adicionar(lista, texto) {
4	  const limpo = String(texto ?? '').trim();
5	  if (!limpo) throw new Error('A pendência precisa de um texto.');
6	  const id = lista.reduce((maior, item) => Math.max(maior, item.id), 0) + 1;
7	  return [...lista, { id, texto: limpo, feita: false }];
8	}
9	
10	export function concluir(lista, id) {
11	  if (!lista.some((item) => item.id === id)) throw new Error(`Não existe pendência ${id}.`);
12	  return lista.map((item) => (item.id === id ? { ...item, feita: true } : item));
13	}
14	
15	export function remover(lista, id) {
16	  if (!lista.some((item) => item.id === id)) throw new Error(`Não existe pendência ${id}.`);
17	  return lista.filter((item) => item.id !== id);
18	}
19	
20	export function abertas(lista) {
21	  return lista.filter((item) => !item.feita);
22	}
23	
24	export function formatar(lista) {
25	  if (lista.length === 0) return 'Nada pendente. Aproveite.';
26	  return lista.map((item) => `${item.feita ? '[x]' : '[ ]'} ${item.id}. ${item.texto}`).join('\n');
27	}
