1	#!/usr/bin/env node
2	// Uso: node src/cli.js <comando> [argumento]
3	//   add "texto"   adiciona uma pendência
4	//   list          mostra todas
5	//   done <id>     marca como feita
6	//   rm <id>       remove
7	import { adicionar, concluir, remover, formatar } from './pendencias.js';
8	import { carregar, salvar } from './armazenamento.js';
9	
10	const [comando, ...resto] = process.argv.slice(2);
11	
12	try {
13	  const lista = await carregar();
14	  if (comando === 'add') {
15	    const nova = adicionar(lista, resto.join(' '));
16	    await salvar(nova);
17	    console.log(`Anotado: ${nova.at(-1).id}. ${nova.at(-1).texto}`);
18	  } else if (comando === 'done') {
19	    await salvar(concluir(lista, Number(resto[0])));
20	    console.log(`Feita: ${resto[0]}.`);
21	  } else if (comando === 'rm') {
22	    await salvar(remover(lista, Number(resto[0])));
23	    console.log(`Removida: ${resto[0]}.`);
24	  } else if (comando === 'list' || comando === undefined) {
25	    console.log(formatar(lista));
26	  } else {
27	    console.error(`Comando desconhecido: ${comando}. Use add, list, done ou rm.`);
28	    process.exitCode = 1;
29	  }
30	} catch (erro) {
31	  console.error(erro.message);
32	  process.exitCode = 1;
33	}
