1	// Guarda a lista num arquivo JSON. O caminho pode ser trocado por variável de ambiente.
2	import { readFile, writeFile } from 'node:fs/promises';
3	
4	export const ARQUIVO = process.env.PENDENCIAS_ARQUIVO ?? 'pendencias.json';
5	
6	export async function carregar(arquivo = ARQUIVO) {
7	  try {
8	    return JSON.parse(await readFile(arquivo, 'utf8'));
9	  } catch (erro) {
10	    if (erro.code === 'ENOENT') return [];
11	    throw erro;
12	  }
13	}
14	
15	export async function salvar(lista, arquivo = ARQUIVO) {
16	  await writeFile(arquivo, JSON.stringify(lista, null, 2) + '\n', 'utf8');
17	}
