1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { adicionar, concluir, remover, abertas, formatar } from '../src/pendencias.js';
4	
5	test('adicionar cria id sequencial e não altera a lista original', () => {
6	  const vazia = [];
7	  const uma = adicionar(vazia, 'comprar café');
8	  const duas = adicionar(uma, 'pagar boleto');
9	  assert.equal(vazia.length, 0);
10	  assert.deepEqual(duas.map((i) => i.id), [1, 2]);
11	  assert.equal(duas[1].feita, false);
12	});
13	
14	test('adicionar recusa texto vazio', () => {
15	  assert.throws(() => adicionar([], '   '), /precisa de um texto/);
16	});
17	
18	test('concluir marca só a pendência pedida', () => {
19	  const lista = adicionar(adicionar([], 'a'), 'b');
20	  const depois = concluir(lista, 2);
21	  assert.deepEqual(depois.map((i) => i.feita), [false, true]);
22	  assert.equal(abertas(depois).length, 1);
23	});
24	
25	test('concluir e remover reclamam de id inexistente', () => {
26	  assert.throws(() => concluir([], 9), /Não existe pendência 9/);
27	  assert.throws(() => remover([], 9), /Não existe pendência 9/);
28	});
29	
30	test('formatar mostra caixas marcadas e lista vazia', () => {
31	  assert.equal(formatar([]), 'Nada pendente. Aproveite.');
32	  const lista = concluir(adicionar([], 'a'), 1);
33	  assert.equal(formatar(lista), '[x] 1. a');
34	});
